-- GetUK Support: osTicket customer-facing email templates and site pages.
-- Generated from a verified local osTicket 1.18.4 install - these exact rows
-- were rendered through osTicket's own mailer and checked for unresolved
-- variables and dead links before export.
--
-- Apply:  mysql -u<user> -p <osticket_db> < apply-templates.sql
-- Adjust the ost_ prefix below if the live install uses a different one.

START TRANSACTION;

UPDATE ost_email_template SET subject='We\'ve got your request [#%{ticket.number}]', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">Thanks &mdash; we\'ve received your request and logged it as ticket <strong>#%{ticket.number}</strong>. It\'s with the team now and someone will come back to you.</p> <p style="margin:0 0 6px;color:#5b5b66;font-size:14px;">Subject: <strong style="color:#111111;">%{ticket.subject}</strong></p> <table cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;"><tr><td style="background:#e31837;border-radius:8px;"><a href="%%7Brecipient.ticket_link%7D" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;">View your ticket</a></td></tr></table> <p style="margin:0;">If anything has changed, or it\'s become more urgent than when you wrote in, just reply and tell us &mdash; it all lands on the same ticket.</p> <p style="margin:14px 0 0;">If something is actually down right now, please call us on <strong>01457 337 247</strong> rather than waiting on email.</p> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p><p style="margin:20px 0 0;padding-top:16px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:13px;">Replying to this email adds your reply straight to the ticket, so please keep it on this thread rather than starting a new one.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='ticket.autoresp';
UPDATE ost_email_template SET subject='Re: %{ticket.subject} [#%{ticket.number}]', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">We\'ve logged your request as ticket <strong>#%{ticket.number}</strong>. Here\'s an answer that may sort it straight away.</p> <p style="margin:0 0 4px;color:#5b5b66;font-size:14px;">Topic: <strong style="color:#111111;">%{ticket.topic.name}</strong></p> <p style="margin:0 0 14px;color:#5b5b66;font-size:14px;">Subject: <strong style="color:#111111;">%{ticket.subject}</strong></p> <div style="margin:0 0 14px;padding:16px 18px;background:#f4f1eb;border-radius:8px;">%{response}</div> <p style="margin:0;">If that hasn\'t done it, reply and say so &mdash; the ticket stays open either way and a real person will pick it up.</p> <table cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;"><tr><td style="background:#e31837;border-radius:8px;"><a href="%%7Brecipient.ticket_link%7D" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;">View your ticket</a></td></tr></table> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p><p style="margin:20px 0 0;padding-top:16px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:13px;">Replying to this email adds your reply straight to the ticket, so please keep it on this thread rather than starting a new one.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='ticket.autoreply';
UPDATE ost_email_template SET subject='Reply received [#%{ticket.number}]', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">Just to confirm we\'ve received your reply and added it to ticket <strong>#%{ticket.number}</strong>. No need to send it again.</p> <table cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;"><tr><td style="background:#e31837;border-radius:8px;"><a href="%%7Brecipient.ticket_link%7D" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;">View your ticket</a></td></tr></table> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p><p style="margin:20px 0 0;padding-top:16px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:13px;">Replying to this email adds your reply straight to the ticket, so please keep it on this thread rather than starting a new one.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='message.autoresp';
UPDATE ost_email_template SET subject='%{ticket.subject} [#%{ticket.number}]', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">We\'ve opened ticket <strong>#%{ticket.number}</strong> on your behalf so there\'s a record of this and you can follow it.</p> <p style="margin:0 0 4px;color:#5b5b66;font-size:14px;">Topic: <strong style="color:#111111;">%{ticket.topic.name}</strong></p> <p style="margin:0 0 14px;color:#5b5b66;font-size:14px;">Subject: <strong style="color:#111111;">%{ticket.subject}</strong></p> <div style="margin:0 0 14px;">%{message}</div> <div style="margin:0 0 14px;">%{response}</div> <table cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;"><tr><td style="background:#e31837;border-radius:8px;"><a href="%%7Brecipient.ticket_link%7D" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;">View your ticket</a></td></tr></table> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p><p style="margin:20px 0 0;padding-top:16px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:13px;">Replying to this email adds your reply straight to the ticket, so please keep it on this thread rather than starting a new one.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='ticket.notice';
UPDATE ost_email_template SET subject='You\'ve reached the open ticket limit', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">You\'ve hit the limit for how many tickets can be open at once, so this latest one hasn\'t been created.</p> <p style="margin:0 0 14px;">That limit is there to stop one issue getting split across several tickets. The quickest thing is to reply on an existing ticket instead &mdash; or if they\'re all genuinely separate and still live, call us on <strong>01457 337 247</strong> and we\'ll raise the limit.</p> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='ticket.overlimit';
UPDATE ost_email_template SET subject='Re: %{ticket.subject} [#%{ticket.number}]', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <div style="margin:0 0 14px;">%{response}</div> <p style="margin:0;">If that\'s sorted it, you don\'t need to do anything. If not, reply here and we\'ll keep going.</p> <table cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;"><tr><td style="background:#e31837;border-radius:8px;"><a href="%%7Brecipient.ticket_link%7D" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;">View your ticket</a></td></tr></table> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p><p style="margin:20px 0 0;padding-top:16px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:13px;">Replying to this email adds your reply straight to the ticket, so please keep it on this thread rather than starting a new one.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='ticket.reply';
UPDATE ost_email_template SET subject='Re: %{ticket.subject} [#%{ticket.number}]', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;letter-spacing:-0.01em;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;">  <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">There\'s an update on ticket <strong>#%{ticket.number}</strong>.</p> <div style="margin:0 0 14px;">%{response}</div> <table cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;"><tr><td style="background:#e31837;border-radius:8px;"><a href="%%7Brecipient.ticket_link%7D" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;">View your ticket</a></td></tr></table> <p style="margin:22px 0 0;color:#5b5b66;">GetUK Support<br />%{signature}</p><p style="margin:20px 0 0;padding-top:16px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:13px;">Replying to this email adds your reply straight to the ticket, so please keep it on this thread rather than starting a new one.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table> </td></tr></table>', updated=NOW() WHERE code_name='ticket.activity.notice';

UPDATE ost_content SET name='Thanks - your ticket is raised', body=' <h1>Thanks, that\'s raised</h1> <p>%{ticket.name}, your request is logged and the team can see it. We\'ve emailed you a confirmation with the ticket number and a link to follow it.</p> <p>If you don\'t see that email in the next few minutes, check your junk folder &mdash; and if it\'s not there either, call us on <strong>01457 337 247</strong> and we\'ll check it landed.</p> <p style="color:#5b5b66;">If something is down right now, please phone rather than wait on email.</p> ', updated=NOW() WHERE type='thank-you';
UPDATE ost_content SET name='Sign in to GetUK Support', body=' Sign in to see everything you\'ve raised with us in one place, along with our replies. You don\'t have to &mdash; you can raise a ticket without an account &mdash; but it\'s easier to keep track this way.', updated=NOW() WHERE type='banner-client';
UPDATE ost_content SET name='Reset your GetUK Support password', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;"> <p style="margin:0 0 14px;">Hello %{user.name.first},</p> <p style="margin:0 0 14px;">Someone asked to reset the password on your support account at %{url}. If that was you, use the link below.</p> <p style="margin:0 0 14px;">%{reset_link}</p> <p style="margin:0 0 14px;">If it wasn\'t you, you can ignore this. Nothing has changed &mdash; your account isn\'t locked and your password still works. Most of the time it\'s simply someone mistyping their own email address.</p> <p style="margin:0;">If you\'d like us to check it over, call the team on <strong>01457 337 247</strong>.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table></td></tr></table>', updated=NOW() WHERE type='pwreset-client';
UPDATE ost_content SET name='Your access link for ticket #%{ticket.number}', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;"> <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">Here\'s the link to ticket <strong>#%{ticket.number}</strong> at %{url}.</p> <p style="margin:0 0 14px;"><a href="%{recipient.ticket_link}" style="color:#e31837;">%{recipient.ticket_link}</a></p> <p style="margin:0;">If you didn\'t ask for this, ignore it &mdash; the link only shows that one ticket and nothing on your account has changed.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table></td></tr></table>', updated=NOW() WHERE type='access-link';
UPDATE ost_content SET name='Your GetUK Support account', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;"> <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">Your support account is set up. Signing in lets you see everything you\'ve raised with us, and our replies, in one place.</p> <p style="margin:0 0 14px;">%{link}</p> <p style="margin:0;">Any trouble getting in, reply to this or call us on <strong>01457 337 247</strong>.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table></td></tr></table>', updated=NOW() WHERE type='registration-client';
UPDATE ost_content SET name='Confirm your email address', body='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f1eb;padding:24px 0;"> <tr><td align="center"> <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border:1px solid #e4e1da;border-radius:12px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,Helvetica,sans-serif;"> <tr><td style="background:#07072f;padding:20px 28px;border-bottom:3px solid #e31837;"> <span style="color:#ffffff;font-size:19px;font-weight:700;">GetUK<span style="color:#e31837;">.Support</span></span> </td></tr> <tr><td style="padding:28px;color:#111111;font-size:15px;line-height:1.6;"> <p style="margin:0 0 14px;">Hello %{recipient.name.first},</p> <p style="margin:0 0 14px;">One last step &mdash; confirm this is your email address and your support account is ready.</p> <p style="margin:0 0 14px;">%{link}</p> <p style="margin:0;">If you didn\'t sign up, ignore this and nothing happens.</p> </td></tr> <tr><td style="background:#f4f1eb;padding:18px 28px;border-top:1px solid #e4e1da;color:#5b5b66;font-size:12px;line-height:1.5;"> Get Group Ltd &middot; UK support division<br /> <a href="https://getuk.support" style="color:#5b5b66;">getuk.support</a> &middot; 01457 337 247 </td></tr> </table></td></tr></table>', updated=NOW() WHERE type='registration-confirm';
UPDATE ost_content SET name='Account confirmed', body=' <h1>You\'re all set</h1> <p>Your email address is confirmed and your support account is ready. You can sign in now to raise a ticket or check anything already open.</p> ', updated=NOW() WHERE type='registration-thanks';

-- osTicket ships with the customer auto-response switched OFF, so nobody gets
-- a 'we've got it' email at all. Branding those emails is pointless while they
-- are never sent, so turn them on.
UPDATE ost_config SET value='1' WHERE namespace='core' AND `key` IN ('ticket_autoresponder','message_autoresponder');

COMMIT;
